// Flatten the function payload rows into the report column order
const COLS = ['entity','deal_id','dealname','final_customer','owner','sales_region','pipeline','stage','probability_pct','amount','currency','amount_kusd','closedate','arr_ky','product_family','product','application','icalps_dealtype','icalps_stage','source','createdate','day1_hot_score','day1_hot_flag','duplicate_suspect','duplicate_of','deal_url'];
return $input.all().map(i => ({ json: Object.fromEntries(COLS.map(c => [c, i.json[c] ?? null])) }));

